-- >>> BEGIN 001_seed_admin_account.sql

-- Seed an admin account for Supabase (idempotent).
-- Run in Supabase SQL Editor (service role / postgres privileges).
--
-- IMPORTANT:
-- 1) Edit v_email / v_password before running.
-- 2) This project currently has no dedicated public.admin table.
--    "admin" is stored in auth.users.raw_app_meta_data.
-- 3) Assumes user_settings and user_security_settings tables already exist.
-- 4) On newer Supabase auth schemas, auth.users.confirmed_at is a generated column.
--    Do not insert/update it directly; set email_confirmed_at instead.

create extension if not exists pgcrypto with schema extensions;

do $$
declare
  v_email text := 'admin@kata.com';
  v_password text := 'Ka@111220';
  v_display_name text := 'System Admin';
  v_currency text := 'USD'; -- Set non-null to mark onboarding complete in template flow
  v_user_id uuid;
  v_now timestamptz := now();
begin
  select u.id
    into v_user_id
  from auth.users u
  where lower(u.email) = lower(v_email)
  limit 1;

  if v_user_id is null then
    v_user_id := gen_random_uuid();

    insert into auth.users (
      id,
      instance_id,
      aud,
      role,
      email,
      encrypted_password,
      email_confirmed_at,
      raw_app_meta_data,
      raw_user_meta_data,
      created_at,
      updated_at
    ) values (
      v_user_id,
      '00000000-0000-0000-0000-000000000000'::uuid,
      'authenticated',
      'authenticated',
      v_email,
      extensions.crypt(v_password, extensions.gen_salt('bf')),
      v_now,
      jsonb_build_object(
        'provider', 'email',
        'providers', jsonb_build_array('email'),
        'role', 'admin',
        'is_admin', true
      ),
      jsonb_build_object(
        'display_name', v_display_name
      ),
      v_now,
      v_now
    );
  else
    update auth.users
    set
      encrypted_password = extensions.crypt(v_password, extensions.gen_salt('bf')),
      email_confirmed_at = coalesce(email_confirmed_at, v_now),
      raw_app_meta_data = coalesce(raw_app_meta_data, '{}'::jsonb) || jsonb_build_object(
        'provider', 'email',
        'providers', jsonb_build_array('email'),
        'role', 'admin',
        'is_admin', true
      ),
      raw_user_meta_data = coalesce(raw_user_meta_data, '{}'::jsonb) || jsonb_build_object(
        'display_name', v_display_name
      ),
      updated_at = v_now
    where id = v_user_id;
  end if;

  if exists (
    select 1
    from auth.identities i
    where i.user_id = v_user_id
      and i.provider = 'email'
  ) then
    update auth.identities
    set
      identity_data = coalesce(identity_data, '{}'::jsonb) || jsonb_build_object(
        'sub', v_user_id::text,
        'email', v_email,
        'email_verified', true
      ),
      last_sign_in_at = coalesce(last_sign_in_at, v_now),
      updated_at = v_now
    where user_id = v_user_id
      and provider = 'email';
  else
    insert into auth.identities (
      id,
      user_id,
      identity_data,
      provider,
      provider_id,
      last_sign_in_at,
      created_at,
      updated_at
    ) values (
      gen_random_uuid(),
      v_user_id,
      jsonb_build_object(
        'sub', v_user_id::text,
        'email', v_email,
        'email_verified', true
      ),
      'email',
      v_user_id::text,
      v_now,
      v_now,
      v_now
    );
  end if;

  insert into public.user_settings (
    user_id,
    currency,
    theme_mode,
    theme,
    theme_variant,
    language,
    background_type
  ) values (
    v_user_id,
    v_currency,
    'light',
    'light',
    'sunset',
    'en',
    'default'
  )
  on conflict (user_id) do update
  set
    currency = excluded.currency,
    theme_mode = excluded.theme_mode,
    theme = excluded.theme,
    theme_variant = excluded.theme_variant,
    language = excluded.language,
    background_type = excluded.background_type,
    updated_at = now();

  insert into public.user_security_settings (
    user_id,
    screen_lock_enabled,
    screen_lock_method,
    screen_lock_pin_hash
  ) values (
    v_user_id,
    false,
    null,
    null
  )
  on conflict (user_id) do nothing;

  raise notice 'Admin user seeded/updated: % (id=%)', v_email, v_user_id;
end $$;

-- <<< END 001_seed_admin_account.sql

-- >>> BEGIN 003_seed_showroom_bootstrap.sql

-- Showroom bootstrap seed (Task 002)
-- Run after: apps/web/sql/002_showroom_core_schema.sql
--
-- Seeds:
-- - default branch
-- - system_settings + branch_settings
-- - branch_opening_hours (7 days)
-- - system customer tags (vip, blacklist warning-only)
-- - showroom page template registry (`PRODUCT_HOME_V1` + charm/modern/3d variants)
-- - showroom page config (published) for customer product home page by locale
-- - profiles/profile_branch_access for admin auth users (if present)

begin;

do $$
declare
  -- Adjust defaults for your project before first run if needed.
  v_branch_code text := 'main';
  v_branch_name text := 'Main Showroom';
  v_branch_timezone text := 'Asia/Ho_Chi_Minh';
  v_currency_code text := 'VND';
  v_branch_id uuid;
  v_admin_profile_id uuid;
  v_product_home_template_id uuid;
  v_template_id uuid;
  v_admin_count integer := 0;
  rec record;
  v_meta jsonb;
  v_user_meta jsonb;
begin
  -- Upsert default branch by case-insensitive code.
  select b.id
    into v_branch_id
  from public.branches b
  where lower(b.code) = lower(v_branch_code)
  limit 1;

  if v_branch_id is null then
    insert into public.branches (
      code,
      name,
      timezone,
      currency_code,
      is_active
    ) values (
      v_branch_code,
      v_branch_name,
      v_branch_timezone,
      v_currency_code,
      true
    )
    returning id into v_branch_id;
  else
    update public.branches
    set
      name = v_branch_name,
      timezone = v_branch_timezone,
      currency_code = v_currency_code,
      is_active = true
    where id = v_branch_id;
  end if;

  -- Singleton global settings.
  insert into public.system_settings (
    default_locale,
    default_currency_code,
    late_fee_mode,
    late_fee_value,
    laundry_tracking_enabled
  ) values (
    'vi',
    v_currency_code,
    'fixed_per_day',
    0,
    true
  )
  on conflict ((true)) do update
  set
    default_locale = excluded.default_locale,
    default_currency_code = excluded.default_currency_code,
    late_fee_mode = excluded.late_fee_mode,
    late_fee_value = excluded.late_fee_value,
    laundry_tracking_enabled = excluded.laundry_tracking_enabled;

  -- Branch override defaults (can be refined later in Settings module).
  insert into public.branch_settings (
    branch_id,
    locale,
    currency_code,
    late_fee_mode,
    late_fee_value,
    laundry_tracking_enabled,
    is_rental_module_enabled,
    is_makeup_module_enabled,
    overdue_reminder_threshold_hours,
    laundry_stuck_threshold_days
  ) values (
    v_branch_id,
    'vi',
    v_currency_code,
    'fixed_per_day',
    0,
    true,
    true,
    true,
    4,
    3
  )
  on conflict (branch_id) do update
  set
    locale = excluded.locale,
    currency_code = excluded.currency_code,
    late_fee_mode = excluded.late_fee_mode,
    late_fee_value = excluded.late_fee_value,
    laundry_tracking_enabled = excluded.laundry_tracking_enabled,
    is_rental_module_enabled = excluded.is_rental_module_enabled,
    is_makeup_module_enabled = excluded.is_makeup_module_enabled,
    overdue_reminder_threshold_hours = excluded.overdue_reminder_threshold_hours,
    laundry_stuck_threshold_days = excluded.laundry_stuck_threshold_days;

  -- Opening hours: Sunday closed, Monday-Saturday open 09:00-20:00.
  for rec in
    select *
    from (
      values
        (0, false, null::time, null::time, null::time, null::time),
        (1, true,  '09:00'::time, '20:00'::time, null::time, null::time),
        (2, true,  '09:00'::time, '20:00'::time, null::time, null::time),
        (3, true,  '09:00'::time, '20:00'::time, null::time, null::time),
        (4, true,  '09:00'::time, '20:00'::time, null::time, null::time),
        (5, true,  '09:00'::time, '20:00'::time, null::time, null::time),
        (6, true,  '09:00'::time, '20:00'::time, null::time, null::time)
    ) as t(day_of_week, is_open, open_time, close_time, break_start_time, break_end_time)
  loop
    insert into public.branch_opening_hours (
      branch_id,
      day_of_week,
      is_open,
      open_time,
      close_time,
      break_start_time,
      break_end_time
    ) values (
      v_branch_id,
      rec.day_of_week,
      rec.is_open,
      rec.open_time,
      rec.close_time,
      rec.break_start_time,
      rec.break_end_time
    )
    on conflict (branch_id, day_of_week) do update
    set
      is_open = excluded.is_open,
      open_time = excluded.open_time,
      close_time = excluded.close_time,
      break_start_time = excluded.break_start_time,
      break_end_time = excluded.break_end_time;
  end loop;

  -- System customer tags. "blacklist" is warning-only by default per PRD.
  for rec in
    select *
    from (
      values
        ('vip', 'VIP', '#f59e0b', true, false, false, true),
        ('blacklist', 'Blacklist', '#ef4444', true, true, false, true)
    ) as t(code, name, color, is_system, warn_on_order_create, block_order_create, is_active)
  loop
    if exists (
      select 1
      from public.customer_tags ct
      where ct.branch_id = v_branch_id
        and lower(ct.code) = lower(rec.code)
    ) then
      update public.customer_tags
      set
        name = rec.name,
        color = rec.color,
        is_system = rec.is_system,
        warn_on_order_create = rec.warn_on_order_create,
        block_order_create = rec.block_order_create,
        is_active = rec.is_active
      where branch_id = v_branch_id
        and lower(code) = lower(rec.code);
    else
      insert into public.customer_tags (
        branch_id,
        code,
        name,
        color,
        is_system,
        warn_on_order_create,
        block_order_create,
        is_active
      ) values (
        v_branch_id,
        rec.code,
        rec.name,
        rec.color,
        rec.is_system,
        rec.warn_on_order_create,
        rec.block_order_create,
        rec.is_active
      );
    end if;
  end loop;

  -- Seed template registry for customer showroom product home page.
  update public.showroom_page_templates
  set
    is_default = false
  where page_key = 'PRODUCT_HOME'
    and lower(code) <> 'product_home_v1'
    and is_default = true;

  select t.id
    into v_product_home_template_id
  from public.showroom_page_templates t
  where lower(t.code) = 'product_home_v1'
  limit 1;

  if v_product_home_template_id is null then
    insert into public.showroom_page_templates (
      code,
      page_key,
      name,
      description,
      template_version,
      config_schema_json,
      is_active,
      is_default
    ) values (
      'PRODUCT_HOME_V1',
      'PRODUCT_HOME',
      'Product Home Page V1',
      'MVP template for customer showroom product home page',
      1,
      jsonb_build_object(
        'pageKey', 'PRODUCT_HOME',
        'version', 1,
        'supports', jsonb_build_array(
          'hero',
          'featured_products',
          'category_grid',
          'search_filters',
          'shortlist_cta'
        )
      ),
      true,
      true
    )
    returning id into v_product_home_template_id;
  else
    update public.showroom_page_templates
    set
      page_key = 'PRODUCT_HOME',
      name = 'Product Home Page V1',
      description = 'MVP template for customer showroom product home page',
      template_version = 1,
      config_schema_json = jsonb_build_object(
        'pageKey', 'PRODUCT_HOME',
        'version', 1,
        'supports', jsonb_build_array(
          'hero',
          'featured_products',
          'category_grid',
          'search_filters',
          'shortlist_cta'
        )
      ),
      is_active = true,
      is_default = true
    where id = v_product_home_template_id;
  end if;

  -- Seed additional product home templates for branch-level selection.
  for rec in
    select *
    from (
      values
        (
          'PRODUCT_HOME_CHARM_V1'::text,
          'Mẫu giao diện dễ thương'::text,
          'Cute storefront style template'::text,
          1::int
        ),
        (
          'PRODUCT_HOME_MODERN_V1'::text,
          'Mẫu giao diện hiện đại'::text,
          'Modern studio storefront template'::text,
          1::int
        ),
        (
          'PRODUCT_HOME_3D_V1'::text,
          'Mẫu giao diện 3D hiện đại'::text,
          'Modern 3D showcase storefront template'::text,
          1::int
        )
    ) as t(code, name, description, template_version)
  loop
    select t.id
      into v_template_id
    from public.showroom_page_templates t
    where lower(t.code) = lower(rec.code)
    limit 1;

    if v_template_id is null then
      insert into public.showroom_page_templates (
        code,
        page_key,
        name,
        description,
        template_version,
        config_schema_json,
        is_active,
        is_default
      ) values (
        rec.code,
        'PRODUCT_HOME',
        rec.name,
        rec.description,
        rec.template_version,
        jsonb_build_object(
          'pageKey', 'PRODUCT_HOME',
          'version', rec.template_version,
          'supports', jsonb_build_array(
            'hero',
            'featured_products',
            'category_grid',
            'search_filters',
            'shortlist_cta'
          )
        ),
        true,
        false
      );
    else
      update public.showroom_page_templates
      set
        page_key = 'PRODUCT_HOME',
        name = rec.name,
        description = rec.description,
        template_version = rec.template_version,
        config_schema_json = jsonb_build_object(
          'pageKey', 'PRODUCT_HOME',
          'version', rec.template_version,
          'supports', jsonb_build_array(
            'hero',
            'featured_products',
            'category_grid',
            'search_filters',
            'shortlist_cta'
          )
        ),
        is_active = true,
        is_default = false
      where id = v_template_id;
    end if;
  end loop;

  -- Seed profiles + branch access for admin users already present in auth.users.
  for rec in
    select
      u.id,
      u.email,
      u.phone,
      coalesce(u.raw_app_meta_data, '{}'::jsonb) as raw_app_meta_data,
      coalesce(u.raw_user_meta_data, '{}'::jsonb) as raw_user_meta_data
    from auth.users u
    where (
      lower(coalesce(u.raw_app_meta_data->>'role', '')) in ('admin', 'owner_admin')
      or lower(coalesce(u.raw_app_meta_data->>'is_admin', 'false')) in ('true', 't', '1')
    )
  loop
    v_meta := rec.raw_app_meta_data;
    v_user_meta := rec.raw_user_meta_data;

    insert into public.profiles (
      id,
      full_name,
      email,
      phone,
      role,
      default_branch_id,
      locale,
      is_active
    ) values (
      rec.id,
      coalesce(
        nullif(v_user_meta->>'display_name', ''),
        nullif(v_user_meta->>'full_name', ''),
        nullif(v_user_meta->>'name', ''),
        nullif(split_part(coalesce(rec.email, ''), '@', 1), ''),
        'Admin'
      ),
      rec.email,
      coalesce(rec.phone, nullif(v_user_meta->>'phone', '')),
      'owner_admin',
      v_branch_id,
      case
        when lower(coalesce(v_user_meta->>'locale', v_meta->>'locale', '')) in ('vi', 'en')
          then lower(coalesce(v_user_meta->>'locale', v_meta->>'locale'))
        else 'vi'
      end,
      true
    )
    on conflict (id) do update
    set
      full_name = coalesce(excluded.full_name, public.profiles.full_name),
      email = coalesce(excluded.email, public.profiles.email),
      phone = coalesce(excluded.phone, public.profiles.phone),
      role = 'owner_admin',
      default_branch_id = coalesce(public.profiles.default_branch_id, excluded.default_branch_id),
      locale = case
        when public.profiles.locale in ('vi', 'en') then public.profiles.locale
        else excluded.locale
      end,
      is_active = true;

    -- Keep one default branch for this profile before marking current branch as default.
    update public.profile_branch_access
    set is_default = false
    where profile_id = rec.id
      and branch_id <> v_branch_id
      and is_default = true;

    insert into public.profile_branch_access (
      profile_id,
      branch_id,
      is_default
    ) values (
      rec.id,
      v_branch_id,
      true
    )
    on conflict (profile_id, branch_id) do update
    set is_default = true;

    v_admin_count := v_admin_count + 1;
  end loop;

  select p.id
    into v_admin_profile_id
  from public.profiles p
  where p.role = 'owner_admin'
    and p.default_branch_id = v_branch_id
    and p.is_active = true
  order by p.created_at asc
  limit 1;

  if v_admin_profile_id is not null then
    update public.branches
    set
      created_by = coalesce(created_by, v_admin_profile_id),
      updated_by = v_admin_profile_id
    where id = v_branch_id;

    update public.system_settings
    set updated_by = v_admin_profile_id;

    update public.branch_settings
    set updated_by = v_admin_profile_id
    where branch_id = v_branch_id;
  end if;

  if v_product_home_template_id is null then
    raise exception 'Failed to seed/showroom template PRODUCT_HOME_V1';
  end if;

  -- Seed published customer showroom page config for PRODUCT_HOME by locale.
  for rec in
    select *
    from (
      values
        (
          'vi'::text,
          'Showroom cho thuê quần áo',
          'Chọn trước trang phục bạn muốn thử trước khi đến shop.',
          'Khám phá bộ sưu tập',
          'Lọc theo size, màu, loại và lưu danh sách đồ muốn thử.'
        ),
        (
          'en'::text,
          'Rental Outfit Showroom',
          'Shortlist outfits before visiting the shop for fitting.',
          'Browse the collection',
          'Filter by size, color, category and save what you want to try on.'
        )
    ) as t(locale, title, subtitle, hero_heading, hero_subheading)
  loop
    insert into public.showroom_page_configs (
      branch_id,
      locale,
      page_key,
      template_id,
      title,
      subtitle,
      hero_config_json,
      sections_config_json,
      filters_config_json,
      seo_config_json,
      display_config_json,
      theme_config_json,
      is_active,
      is_published,
      created_by,
      updated_by
    ) values (
      v_branch_id,
      rec.locale,
      'PRODUCT_HOME',
      v_product_home_template_id,
      rec.title,
      rec.subtitle,
      jsonb_build_object(
        'heading', rec.hero_heading,
        'subheading', rec.hero_subheading,
        'showSearchBox', true,
        'showShortlistCta', true
      ),
      jsonb_build_array(
        jsonb_build_object('key', 'hero', 'enabled', true, 'order', 1),
        jsonb_build_object('key', 'featured_products', 'enabled', true, 'order', 2, 'limit', 12),
        jsonb_build_object('key', 'category_grid', 'enabled', true, 'order', 3),
        jsonb_build_object('key', 'recently_viewed', 'enabled', false, 'order', 4)
      ),
      jsonb_build_object(
        'category', true,
        'tag', true,
        'gender', true,
        'size', true,
        'color', true,
        'textSearch', true
      ),
      jsonb_build_object(
        'title', rec.title,
        'description', rec.subtitle
      ),
      jsonb_build_object(
        'showPriceReference', true,
        'showDepositReference', true,
        'showShortlist', true,
        'cardVariant', 'classic_grid_v1'
      ),
      null,
      true,
      true,
      v_admin_profile_id,
      v_admin_profile_id
    )
    on conflict (branch_id, locale, page_key) do update
    set
      template_id = excluded.template_id,
      title = excluded.title,
      subtitle = excluded.subtitle,
      hero_config_json = excluded.hero_config_json,
      sections_config_json = excluded.sections_config_json,
      filters_config_json = excluded.filters_config_json,
      seo_config_json = excluded.seo_config_json,
      display_config_json = excluded.display_config_json,
      theme_config_json = excluded.theme_config_json,
      is_active = true,
      is_published = true,
      updated_by = coalesce(v_admin_profile_id, public.showroom_page_configs.updated_by);
  end loop;

  raise notice
    'Showroom bootstrap seed completed. branch_id=%, admin_profiles_seeded=%, product_home_template_id=%',
    v_branch_id,
    v_admin_count,
    v_product_home_template_id;
end $$;

commit;

-- <<< END 003_seed_showroom_bootstrap.sql

-- >>> BEGIN 012_seed_default_categories_women_party_outing.sql

-- =========================================================
-- 012_seed_default_categories_women_party_outing.sql
-- Purpose:
-- - Seed default branch-scoped product categories for women's party / outing rental shops.
-- - Idempotent:
--   + update existing branch product-category rows by `branch_id + code` (case-insensitive)
--   + insert missing rows
-- =========================================================

with target_branches as (
  -- Prefer active branches. If there is no active branch, fallback to all branches.
  select b.id
  from public.branches b
  where b.is_active = true

  union all

  select b.id
  from public.branches b
  where not exists (
    select 1 from public.branches bx where bx.is_active = true
  )
),
seed_rows(code, name, slug, sort_order) as (
  values
    ('NU_DA_HOI', 'Váy dạ hội', 'vay-da-hoi', 10),
    ('NU_DU_TIEC', 'Váy dự tiệc', 'vay-du-tiec', 20),
    ('NU_COCKTAIL', 'Đầm cocktail', 'dam-cocktail', 30),
    ('NU_BODY', 'Đầm body', 'dam-body', 40),
    ('NU_MAXI', 'Đầm maxi đi chơi', 'dam-maxi-di-choi', 50),
    ('NU_SET_DI_CHOI', 'Set đồ đi chơi nữ', 'set-do-di-choi-nu', 60),
    ('NU_CONG_SO', 'Set công sở nữ', 'set-cong-so-nu', 70),
    ('NU_JUMPSUIT', 'Jumpsuit nữ', 'jumpsuit-nu', 80),
    ('NU_BLAZER', 'Blazer nữ', 'blazer-nu', 90),
    ('NU_CHAN_VAY', 'Chân váy nữ', 'chan-vay-nu', 100)
),
source_rows as (
  select
    tb.id as branch_id,
    s.code,
    s.name,
    s.slug,
    s.sort_order
  from target_branches tb
  cross join seed_rows s
),
updated_rows as (
  update public.product_categories as c
  set
    name = src.name,
    slug = coalesce(c.slug, src.slug),
    sort_order = src.sort_order,
    is_active = true,
    updated_at = now()
  from source_rows as src
  where c.branch_id = src.branch_id
    and lower(c.code) = lower(src.code)
  returning c.id
)
insert into public.product_categories (
  branch_id,
  code,
  name,
  slug,
  sort_order,
  is_active
)
select
  src.branch_id,
  src.code,
  src.name,
  src.slug,
  src.sort_order,
  true as is_active
from source_rows as src
where not exists (
  select 1
  from public.product_categories as c
  where c.branch_id = src.branch_id
    and lower(c.code) = lower(src.code)
);

-- <<< END 012_seed_default_categories_women_party_outing.sql
